
    #[test]
    fn child_complete_group_source_candidate_registry_returns_original_pages_to_real_parent(){
        mod registry{include!("./🧩️child-operations/🪪️registry/🦀️.rs");}
        use semio_framework_value::{ErasedSnapshotRetirement,retirement::allocation_return::{ParentAllocationReturn,AllocationReturnStep},list::PagedListReturnProgress,ValueError};
        use semio_framework_tool_machine::{ScrubLedger,ScrubInput,ToolStep};
        use semio_framework_os_kernel::{ActorId,HybridLogicalTimestamp,os_pack::codec::PackEncodeOptions};
        impl registry::RetainedOwnerParentReturn for paged_owner::PagedChildOwner{fn return_owner_one<const P:usize>(&mut self,parent:&mut ParentAllocationReturn<P>,items:usize,bytes:usize)->Result<PagedListReturnProgress,ValueError>{self.return_one(parent,items,bytes)}}
        let fixture:serde_json::Value=serde_json::from_str(include_str!("@REGISTRY_PARENT_FIXTURE@")).unwrap();assert_eq!(fixture["sourceBytes"],8194);assert_eq!(fixture["sourceCount"],2);assert_eq!(fixture["maximumAllocationBytes"],65536);assert_eq!(fixture["maximumItems"],1);assert_eq!(fixture["maximumBytes"],4096);assert_eq!(fixture["parentSlots"],1);
        fn child(control:&mut NativeEncodeControl<'_>)->paged_owner::PagedChildOwner{let options=PackEncodeOptions::default();let mut owner=paged_owner::PagedChildOwner::empty();for(field,text)in[(reader::ChildGroupText::Owner,"owner"),(reader::ChildGroupText::Slot,"slot"),(reader::ChildGroupText::ChildId,"child"),(reader::ChildGroupText::Schema,"child.empty")]{owner.read_metadata_from_encoding_source(field,&text,&options,control).unwrap();}let mut receipt=owner.produce_owned_operation(8194,&options,control,|_,output,control|{output.write_bytes(b"17",control)?;for _ in 0..8192{output.write_bytes(b" ",control)?;}Ok(())}).unwrap();receipt.read_first_schema_from_source(&"label.set-label",control).unwrap();for terminology in semio_framework_ui_locale::Terminology::ALL{for locale in semio_framework_ui_locale::Locale::ALL{receipt.read_label_from_source(terminology,locale,&"label",control).unwrap();}}receipt.commit(control).unwrap();owner}
        fn physical(parent:&mut ParentAllocationReturn<1>)->usize{if parent.terminal_is_empty(){return 0}let required=parent.next_close_byte_demand();assert!(required<=4096);assert_eq!(parent.close_step(1,required.saturating_sub(1)),AllocationReturnStep::Pending{released_items:0,released_bytes:0});match parent.close_step(1,4096){AllocationReturnStep::Pending{released_items,released_bytes}=>{assert_eq!(released_items,1);assert_eq!(released_bytes,required);released_bytes},AllocationReturnStep::Complete=>panic!("real parent token disappeared")}}
        let mut allow=|_|true;let mut control=NativeEncodeControl::new(65536,&mut allow);let first=child(&mut control);let first_bytes=first.allocated_bytes();let first_pointer=first.operations[0].byte_ref(0).map(|byte|byte as *const u8).unwrap();let second=child(&mut control);let second_bytes=second.allocated_bytes();let second_pointer=second.operations[0].byte_ref(0).map(|byte|byte as *const u8).unwrap();assert_ne!(first_pointer,second_pointer);let mut owner=registry::RetainedSourceRegistry::empty();let one=owner.insert(&mut Some(first),&mut control).unwrap();let two=owner.insert(&mut Some(second),&mut control).unwrap();let metadata=owner.allocated_bytes();let allocated=first_bytes+second_bytes+metadata;assert_eq!(allocated,control.owned_bytes());assert!(allocated<=65536);
        let actor=ActorId("actor".into());let clock=|physical_ms|HybridLogicalTimestamp{actor:0,physical_ms,logical:0};let mut ledger=ScrubLedger::default();ledger.send("window","tool",&actor,"base",ScrubInput::Tick{gesture:"press".into(),leaves:vec![one]},clock(1)).unwrap();ledger.send("window","tool",&actor,"base",ScrubInput::Tick{gesture:"press".into(),leaves:vec![two]},clock(2)).unwrap();owner.reconcile(|identity,control|{control.checkpoint()?;Ok(ledger.provisional().any(|accepted|*accepted==identity))},&mut control).unwrap();assert!(owner.borrow(one).is_none());assert_eq!(owner.borrow(two).unwrap().operations[0].byte_ref(0).map(|byte|byte as *const u8),Some(second_pointer));
        let mut parent=ParentAllocationReturn::<1>::try_new(4096,65536).unwrap();let mut blocker=vec![0u8];assert!(parent.return_bytes(&mut blocker,1).unwrap());assert_eq!(blocker.capacity(),0);assert!(!owner.return_one(&mut parent,0,4096).unwrap().progressed);let mut frontier=false;for _ in 0..8450{let step=owner.return_one(&mut parent,1,4096).unwrap();assert_eq!(step.returned_allocation_bytes,0);assert_eq!(parent.retained_bytes(),1);assert_eq!(owner.retained_count(),2);if !step.progressed{frontier=true;break;}}assert!(frontier,"full parent never retained the actual empty source-page frontier");let before=owner.allocated_bytes();assert!(!owner.return_one(&mut parent,1,4096).unwrap().progressed);assert_eq!(owner.allocated_bytes(),before);assert_eq!(parent.retained_bytes(),1);let mut disposed=physical(&mut parent);assert_eq!(disposed,1);let mut returned=0;
        for _ in 0..8450{if owner.retained_count()==1{break}disposed+=physical(&mut parent);let before=parent.retained_bytes();let step=owner.return_one(&mut parent,1,4096).unwrap();assert!(step.progressed);assert_eq!(parent.retained_bytes()-before,step.returned_allocation_bytes);returned+=step.returned_allocation_bytes;assert_eq!(owner.borrow(two).unwrap().operations[0].byte_ref(0).map(|byte|byte as *const u8),Some(second_pointer));}disposed+=physical(&mut parent);assert_eq!(owner.retained_count(),1);assert_eq!(returned,first_bytes);assert_eq!(disposed,first_bytes+1);assert_eq!(owner.allocated_bytes(),metadata);assert!(!owner.terminal_is_empty());
        let ToolStep::Committed(_,leaves)=ledger.send("window","tool",&actor,"base",ScrubInput::Commit{gesture:"press".into(),leaves:vec![two]},clock(3)).unwrap()else{panic!("accepted real ledger did not commit")};assert_eq!(leaves,vec![two]);let mut published=owner.take(two,&mut control).unwrap();assert_eq!(published.operations[0].byte_ref(0).map(|byte|byte as *const u8),Some(second_pointer));assert_eq!(published.operations[0].len(),8194);for(index,byte)in published.operations[0].iter().enumerate(){assert_eq!(byte,if index==0{b'1'}else if index==1{b'7'}else{b' '});}owner.reconcile(|identity,control|{control.checkpoint()?;Ok(ledger.provisional().any(|accepted|*accepted==identity))},&mut control).unwrap();assert!(owner.take(two,&mut control).is_err());assert_eq!(owner.allocated_bytes(),metadata);
        for _ in 0..8450{if published.terminal_is_empty(){break}disposed+=physical(&mut parent);let before=parent.retained_bytes();let step=published.return_one(&mut parent,1,4096).unwrap();assert!(step.progressed);assert_eq!(parent.retained_bytes()-before,step.returned_allocation_bytes);returned+=step.returned_allocation_bytes;}disposed+=physical(&mut parent);assert!(published.terminal_is_empty());assert_eq!(returned,first_bytes+second_bytes);assert_eq!(owner.retained_count(),0);assert!(!owner.terminal_is_empty());owner.begin_close();for _ in 0..8450{if owner.terminal_is_empty(){break}disposed+=physical(&mut parent);let before=parent.retained_bytes();let step=owner.return_one(&mut parent,1,4096).unwrap();assert!(step.progressed);assert_eq!(parent.retained_bytes()-before,step.returned_allocation_bytes);returned+=step.returned_allocation_bytes;}disposed+=physical(&mut parent);assert!(owner.terminal_is_empty()&&parent.terminal_is_empty());assert_eq!(returned,allocated);assert_eq!(disposed,allocated+1);
        eprintln!("[DEBUG] actual accepted scalar ledger preserves second original8194 pointer through displaced first-source parent handback; full one-slot parent frontier retains backing; committed extraction precedes accepted-empty reconcile; child+registry transfer actual layouts with zero physical credit, real parent disposes every original nested allocation1/4096");
    }
